//! **Every accepted corpus program is CERTIFIED in Lean or NAMED -- nothing falls between.**
//!
//! Certificates are GENERATED ON DEMAND and never stored in the repository (Simon, 2026-10-17:
//! no regenerable generated files). For every `.gab` under `beispiele/` (top level and `gift/`)
//! that the checker accepts (the path `gabbro lean-g` takes: `lies`, `pruefe`, no error):
//!
//! * the exporter carries it (`obligations_g::export` answers `Ok`) => the output is the
//!   certificate: it must decide the checker premise (`gCheck … := by decide`), instantiate the
//!   goal theorem (`gP_gabbro_f`) and contain no `sorry`/`native_decide`/`admit`. It is written
//!   to `target/zertifikate/<namespace>.lean`, where `instrumente/pruefe-lean.py` (stage 5)
//!   elaborates it with `lake env lean` against the built model: the Lean Bool `Akzeptiert`
//!   refusing an exported unit turns that guardian RED;
//! * the exporter refuses it => the refusal code is one of `LG001`-`LG007` and is counted.
//!
//! The totals are printed (`--nocapture`); the register of which programs are certified is
//! `target/zertifikate/REGISTER.txt`, rewritten on every run.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

fn wurzel() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("..")
}

/// Every `.gab` under `beispiele/` and `beispiele/gift/`, as `beispiele/…`, sorted.
fn programme(w: &Path) -> Vec<String> {
    let mut out = Vec::new();
    for dir in ["beispiele", "beispiele/gift"] {
        let Ok(rd) = std::fs::read_dir(w.join(dir)) else { continue };
        for e in rd.flatten() {
            let name = e.file_name().to_string_lossy().to_string();
            if name.ends_with(".gab") && e.path().is_file() {
                out.push(format!("{dir}/{name}"));
            }
        }
    }
    out.sort();
    out
}

fn marker(rel: &str) -> String {
    format!(
        "-- GENERATED by `gabbro obligations --g {rel}` (lean-g export plus the stated \
         obligation) -- do not edit."
    )
}

fn eine_zeile(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

#[test]
fn jedes_angenommene_programm_ist_zertifiziert_oder_benannt() {
    let w = wurzel();
    let ziel = w.join("target").join("zertifikate");
    let _ = std::fs::remove_dir_all(&ziel);
    std::fs::create_dir_all(&ziel).expect("mkdir target/zertifikate");

    let mut befunde: Vec<String> = Vec::new();
    let mut register = String::from("# generated by tests/zertifikate.rs on every run; never committed\n");
    let mut namensraeume: BTreeMap<String, String> = BTreeMap::new();
    let (mut n_ang, mut n_zert, mut n_nicht) = (0usize, 0usize, 0usize);

    for rel in programme(&w) {
        let quelle = std::fs::read_to_string(w.join(&rel)).expect("readable");
        let (baum, mut absagen) = gabbro_syntax::lies(&rel, &quelle);
        gabbro_check::pruefe(&baum, &mut absagen);
        if absagen.fehler_zahl() > 0 {
            continue; // not accepted: no claim, nothing to certify
        }
        n_ang += 1;
        match gabbro_check::obligations_g::export(&rel, &baum) {
            Ok(text) => {
                n_zert += 1;
                let ns = gabbro_check::lean_g::namespace_of(&rel);
                if let Some(anderes) = namensraeume.insert(ns.clone(), rel.clone()) {
                    befunde.push(format!("{rel} and {anderes} share the namespace {ns}"));
                }
                assert!(text.starts_with(&marker(&rel)), "generator marker moved");
                for teil in [
                    "theorem gCheck : Zielsatz.akzeptiertX_pruefer.akzeptiert gE gFs gLs gCs = true := by decide",
                    "theorem gP_gabbro_f",
                    "Zielsatz.gabbro_ziel Zielsatz.akzeptiertX_pruefer gD gE",
                ] {
                    if !text.contains(teil) {
                        befunde.push(format!("{rel}: the certificate lacks {teil:?}"));
                    }
                }
                for verboten in ["sorry", "native_decide", "admit"] {
                    if text.contains(verboten) {
                        befunde.push(format!("{rel}: the certificate contains `{verboten}`"));
                    }
                }
                std::fs::write(ziel.join(format!("{ns}.lean")), &text).expect("write certificate");
                register.push_str(&format!("CERTIFIED\t{rel}\t{ns}\n"));
            }
            Err(r) => {
                n_nicht += 1;
                if !(r.code.starts_with("LG00") && r.code.len() == 5) {
                    befunde.push(format!("{rel}: refusal code {} is not one of LG001-LG007", r.code));
                }
                register.push_str(&format!("UNCERTIFIED\t{rel}\t{}\t{}\n", r.code, eine_zeile(&r.message)));
            }
        }
    }
    register.push_str(&format!("# TOTAL: {n_ang} accepted, {n_zert} CERTIFIED, {n_nicht} UNCERTIFIED\n"));
    std::fs::write(ziel.join("REGISTER.txt"), &register).expect("write register");
    println!("zertifikate: {n_ang} accepted, {n_zert} certified, {n_nicht} named refusals");

    assert_eq!(n_ang, n_zert + n_nicht);
    assert!(n_ang > 100, "the population is not the corpus ({n_ang} accepted)");
    assert!(
        befunde.is_empty(),
        "{} finding(s):\n  {}",
        befunde.len(),
        befunde.join("\n  ")
    );
}
